public interface PaymentMethodStrategy {
    void processPayment(String securityCode);
}

public class PaypalPaymentMethod implements PaymentMethodStrategy {
    @Override
    public void processPayment(String securityCode) {
        System.out.println("Processing paypal payment");
        System.out.println("Verifying email: " + securityCode);
    }
}

public class CreditCardPaymentMethod implements PaymentMethodStrategy {
    @Override
    public void processPayment(String securityCode) {
        System.out.println("Processing credit card payment");
        System.out.println("Verifying security code: " + securityCode);
    }
}

public class DebitCardPaymentMethod implements PaymentMethodStrategy {
    @Override
    public void processPayment(String securityCode) {
        System.out.println("Processing debit card payment");
        System.out.println("Verifying security code: " + securityCode);
    }
}

public class PaymentProcessor {
    private PaymentMethodStrategy strategy;

    public PaymentProcessor(PaymentMethodStrategy strategy) {
        this.strategy = strategy;
    }

    public void pay(OrderStatus orderStatus, String securityCode) {
        strategy.processPayment(securityCode);
        orderStatus.setStatus("paid");
    }
}
